<script setup lang="ts">
import type { WeakTopicDetail } from '~/types/domain'; import { resourceRoute } from '~/utils/format'
definePageMeta({ layout:'app' }); const route=useRoute(); const api=useApi(); const detail=ref<WeakTopicDetail>(); const loading=ref(true); async function load(){loading.value=true;try{detail.value=await api.get(`/weak-topics/${route.params.id}`)}finally{loading.value=false}} useSeoMeta({title:()=>detail.value?.resourceTitle??'Weak topic'}); onMounted(load)
</script>
<template><div><CoreLoadingState v-if="loading" label="Loading weakness evidence" /><template v-else-if="detail"><CorePageHeader :title="detail.resourceTitle" description="Why this topic currently needs attention."><CoreStatusBadge :value="detail.level" /></CorePageHeader><section class="weak-detail"><article class="score"><span>Weakness score</span><strong>{{ detail.score }}</strong><p>{{ detail.signalCount }} signals were observed in the active evidence window.</p><UButton :to="resourceRoute(detail.resourceType,detail.resourceId)" label="Practice resource" /></article><article><h2>Signal explanation</h2><div v-for="group in detail.signalGroups" :key="group.signalType" class="signal"><div><strong>{{ group.signalType }}</strong><p>{{ group.count }} occurrences</p></div><span>{{ group.totalWeightedScore }} weighted points</span></div><h2>Recent evidence</h2><div v-for="item in detail.contributions.slice(0,10)" :key="`${item.signalType}-${item.occurredAtUtc}`" class="evidence"><span>{{ item.signalType }}</span><span>Base {{ item.baseWeight }} × {{ item.recencyMultiplier }} = {{ item.weightedScore }}</span></div></article></section></template></div></template>
